import com.tencent.shadow.core.loader.classloaders.PluginClassLoader;import java.nio.file.*;
public class FastPathHarness{public static void main(String[]args)throws Exception{byte[] b=Files.readAllBytes(Paths.get(args[0]));PluginClassLoader p=new PluginClassLoader(true,b);Class<?> c=p.loadClass("ObfuscatedFixture");if(c.getClassLoader()!=p||p.defaultProbes!=0||p.finds!=1)throw new AssertionError("own fast path");for(int i=0;i<10000;i++)if(p.loadClass("ObfuscatedFixture")!=c)throw new AssertionError();if(p.finds!=1||p.defaultProbes!=0)throw new AssertionError("positive cache");if(p.loadClass("java.lang.String")!=String.class||p.probes<1)throw new AssertionError("platform path changed");try{p.loadClass("MissingDefaultFixture");throw new AssertionError();}catch(ClassNotFoundException expected){}if(p.defaultProbes!=1)throw new AssertionError("default absent fallback not preserved");PluginClassLoader dependent=new PluginClassLoader(false,b);if(dependent.loadClass("ObfuscatedFixture").getClassLoader()==dependent)throw new AssertionError("dependent parent-first changed");System.out.println("PASS plugin default class bypasses parent misses; repeat uses findLoadedClass; missing/default fallback, platform route, dependency parent-first preserved");}}
